// Meta connects the webhook with a GET: it gets its hub.challenge back only if hub.verify_token
// matches a token stored in wa_webhook_config for a club on this bot. While no club has a token
// stored, the challenge is echoed as before, so re-connecting the live app keeps working until a
// token is set. The staging build bakes the staging token in (VERIFY_FALLBACK).
const H=this.helpers;
const VERIFY_FALLBACK='';
try{
const SUPA='__SUPABASE_URL__',SR='__SUPABASE_SERVICE_KEY__';
const sH={apikey:SR,Authorization:'Bearer '+SR};
const q=($input.first().json||{}).query||{};
let tokens=[];
try{
  const r=await H.httpRequest({method:'GET',url:SUPA+'/rest/v1/wa_webhook_config?select=verify_token&verify_token=not.is.null',headers:sH,json:true,returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:8000});
  if(r.statusCode<300&&Array.isArray(r.body)) tokens=r.body.map(x=>String(x.verify_token||'')).filter(Boolean);
}catch(e){}
if(VERIFY_FALLBACK&&!tokens.includes(VERIFY_FALLBACK)) tokens.push(VERIFY_FALLBACK);
const given=String(q['hub.verify_token']||'');
const ok=q['hub.mode']==='subscribe'&&(tokens.length?tokens.includes(given):true);
return [{json:{ok,challenge:ok?String(q['hub.challenge']||''):'forbidden',code:ok?200:403,token_checked:tokens.length>0}}];
}catch(e){ return [{json:{ok:false,challenge:'error',code:500}}]; }

// WhatsApp bot for every club on this n8n (the club is found from the WhatsApp phone number id).
// For each event Meta sends:
//  1. The signature (X-Hub-Signature-256) is checked with the club's Meta app secret from
//     wa_webhook_config. While no secret is stored for a club, its events are accepted as before
//     and marked "unverified" in the execution result.
//  2. Delivery statuses go to wa_status_apply (the message's status in the Inbox and the campaign
//     report) and to the campaign's recipient list, as before.
//  3. A member message is stored FIRST. Its WhatsApp id is unique, so a retry of the same event from
//     Meta is recognised and ignored. If staff paused the bot for this number (Inbox: Pause bot, or
//     automatically after a staff reply), the bot stops there: the message still shows in the Inbox.
//  4. Otherwise the bot answers as before: the menu, the club's fixed texts from its settings
//     (bot_config), or the AI. The answer is stored with its WhatsApp id, sender "bot" and
//     sent/failed status. A lead is posted at most once a day per topic and number.
// Works before sql/wa_inbox.sql has been run: it then stores messages the old way and never pauses.
const H=this.helpers;
try{
const SUPA='__SUPABASE_URL__',SR='__SUPABASE_SERVICE_KEY__',GK='__GEMINI_KEY__',LEAD='https://n8n.example.com/webhook/client-lead';
/* tried in order: the first answer wins; a model Google no longer serves (404) is skipped at once */
const AI_MODELS=['gemini-2.5-flash','gemini-2.5-flash-lite','gemini-3.6-flash','gemini-3.1-flash-lite'];
const G='https://graph.facebook.com/v20.0/';
const sH={apikey:SR,Authorization:'Bearer '+SR,'Content-Type':'application/json'};
const item=$input.first(); const inp=item.json||{};
const reqHeaders=inp.headers||{};

// ---- the exact bytes Meta signed (webhook option "Raw Body"), and the parsed event ----
let raw=null;
try{ if(item.binary&&item.binary.data&&typeof H.getBinaryDataBuffer==='function'){ const b=await H.getBinaryDataBuffer(0,'data'); if(b&&b.length) raw=new Uint8Array(Buffer.from(b)); } }catch(e){}
if(!raw){ try{ const bd=item.binary&&item.binary.data; if(bd&&bd.data&&!bd.id) raw=new Uint8Array(Buffer.from(bd.data,'base64')); }catch(e){} }
let body=(inp.body&&typeof inp.body==='object'&&Object.keys(inp.body).length)?inp.body:null;
if(!body&&raw){ try{ body=JSON.parse(Buffer.from(raw).toString('utf8')); }catch(e){} }
body=body||{};
const hdr=(n)=>{ n=n.toLowerCase(); for(const k in reqHeaders){ if(String(k).toLowerCase()===n) return String(reqHeaders[k]||''); } return ''; };

// ---- SHA-256 / HMAC without any module (Code nodes here cannot load crypto) ----
const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
function sha256Bytes(bytes){
  let Hh=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l=bytes.length, padLen=((l+9+63)>>6)<<6; const p=new Uint8Array(padLen); p.set(bytes); p[l]=0x80;
  const bits=l*8, hi=Math.floor(bits/4294967296), lo=bits>>>0;
  p[padLen-8]=(hi>>>24)&255; p[padLen-7]=(hi>>>16)&255; p[padLen-6]=(hi>>>8)&255; p[padLen-5]=hi&255;
  p[padLen-4]=(lo>>>24)&255; p[padLen-3]=(lo>>>16)&255; p[padLen-2]=(lo>>>8)&255; p[padLen-1]=lo&255;
  const w=new Array(64); const rotr=(x,n)=>(x>>>n)|(x<<(32-n));
  for(let i=0;i<padLen;i+=64){
    for(let t=0;t<16;t++) w[t]=(p[i+t*4]<<24)|(p[i+t*4+1]<<16)|(p[i+t*4+2]<<8)|p[i+t*4+3];
    for(let t=16;t<64;t++){ const s0=rotr(w[t-15],7)^rotr(w[t-15],18)^(w[t-15]>>>3); const s1=rotr(w[t-2],17)^rotr(w[t-2],19)^(w[t-2]>>>10); w[t]=(w[t-16]+s0+w[t-7]+s1)|0; }
    let a=Hh[0],b=Hh[1],c=Hh[2],d=Hh[3],e=Hh[4],f=Hh[5],g=Hh[6],h=Hh[7];
    for(let t=0;t<64;t++){ const S1=rotr(e,6)^rotr(e,11)^rotr(e,25), ch=(e&f)^(~e&g), t1=(h+S1+ch+K[t]+w[t])|0, S0=rotr(a,2)^rotr(a,13)^rotr(a,22), mj=(a&b)^(a&c)^(b&c), t2=(S0+mj)|0; h=g;g=f;f=e;e=(d+t1)|0;d=c;c=b;b=a;a=(t1+t2)|0; }
    Hh=[(Hh[0]+a)|0,(Hh[1]+b)|0,(Hh[2]+c)|0,(Hh[3]+d)|0,(Hh[4]+e)|0,(Hh[5]+f)|0,(Hh[6]+g)|0,(Hh[7]+h)|0];
  }
  const out=new Uint8Array(32); Hh.forEach((x,i)=>{ out[i*4]=(x>>>24)&255; out[i*4+1]=(x>>>16)&255; out[i*4+2]=(x>>>8)&255; out[i*4+3]=x&255; });
  return out;
}
const hex=(u)=>Array.from(u,x=>x.toString(16).padStart(2,'0')).join('');
function hmacHex(secret,msg){
  let key=new Uint8Array(Buffer.from(String(secret),'utf8')); if(key.length>64) key=sha256Bytes(key);
  const k=new Uint8Array(64); k.set(key);
  const inner=new Uint8Array(64+msg.length), outer=new Uint8Array(96);
  for(let i=0;i<64;i++){ inner[i]=k[i]^0x36; outer[i]=k[i]^0x5c; }
  inner.set(msg,64); outer.set(sha256Bytes(inner),64);
  return hex(sha256Bytes(outer));
}
const sameStr=(a,b)=>{ a=String(a||''); b=String(b||''); let r=a.length^b.length; for(let i=0;i<Math.max(a.length,b.length);i++) r|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0); return r===0; };

// ---- helpers for Supabase ----
const get=async(path)=>{ const r=await H.httpRequest({method:'GET',url:SUPA+'/rest/v1/'+path,headers:sH,json:true,returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:12000}); return r.statusCode<300?r.body:null; };
const rpc=async(fn,args)=>{ const r=await H.httpRequest({method:'POST',url:SUPA+'/rest/v1/rpc/'+fn,headers:sH,body:JSON.stringify(args),json:true,returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:12000}); return {ok:r.statusCode<300,status:r.statusCode,body:r.body}; };

// ---- which clubs this event is for, and their app secrets ----
const changes=[]; for(const en of (body.entry||[])) for(const ch of (en.changes||[])) if(ch&&ch.value) changes.push(ch.value);
const tenants={};
async function tenantFor(pnid){
  if(!pnid) return null;
  if(tenants[pnid]!==undefined) return tenants[pnid];
  const t=await get('tenants?wa_phone_number_id=eq.'+encodeURIComponent(pnid)+'&select=id,name,slug,bot_config,wa_token,wa_phone_number_id,espo_team_id');
  tenants[pnid]=Array.isArray(t)&&t[0]?t[0]:null; return tenants[pnid];
}
const secrets=[], secretOf={};
for(const v of changes){ const t=await tenantFor(v.metadata&&v.metadata.phone_number_id);
  if(t&&secretOf[t.id]===undefined){ const c=await get('wa_webhook_config?tenant_id=eq.'+t.id+'&select=app_secret'); secretOf[t.id]=(Array.isArray(c)&&c[0]&&c[0].app_secret)||null; if(secretOf[t.id]&&!secrets.includes(secretOf[t.id])) secrets.push(secretOf[t.id]); } }
let verified='unverified (no app secret stored for this club)', okSecrets=[];
if(secrets.length){
  const sig=hdr('x-hub-signature-256');
  if(!raw) return [{json:{ok:false,error:'raw body unavailable: cannot check the signature (enable "Raw Body" on the webhook node)'}}];
  okSecrets=secrets.filter(s=>sameStr(sig,'sha256='+hmacHex(s,raw)));
  if(!okSecrets.length) return [{json:{ok:false,error:'signature mismatch: event ignored'}}];
  verified='verified';
}
/* each club's part of the event must be signed with THAT club's own secret: a body signed with another
   club's secret is refused for a club that has one; a club without a secret stays "unverified" */
const clubCheck=(t)=>{ const s=t?secretOf[t.id]:null; return !s?'unverified':(okSecrets.includes(s)?'verified':'mismatch'); };

// ---- one member message (defined before the loop that uses it) ----
async function handleMessage(tenant,msg){
const from=String(msg.from);
const tid=tenant.id;
const cfg=tenant.bot_config||{}; const brand=cfg.brand||{name:tenant.name};
/* shorten to n characters without splitting an emoji (half an emoji is refused by the database and by Meta) */
const cut=(s,n)=>{ s=String(s==null?'':s); if(s.length<=n) return s; let t=s.slice(0,n); if(/[\uD800-\uDBFF]$/.test(t)) t=t.slice(0,-1); return t; };
const FOOT=cut(brand.tagline||brand.name||'',60);
/* the start of today in India (UTC+5:30), as the admin dashboard's "Today & upcoming" */
const dayStart=()=>{ const d=new Date(Date.now()+19800000); d.setUTCHours(0,0,0,0); return new Date(d.getTime()-19800000); };
const _c=cfg.contact||{}; const _w=String(_c.website||'').trim();
const WEB=_w?(/^https?:/i.test(_w)?_w:'https://'+_w.replace(/^\/+/,'')):'';
const MAPS=String(_c.maps||'').trim(); const BANNER=String((brand.banner_url||'')).trim();
const MAINT=String(cfg.maintenance||'').trim();
const UPI=(function(){ const u=String(((cfg.payments||{}).upi_id)||'').trim(); return /^[A-Za-z0-9._-]{2,64}@[A-Za-z][A-Za-z0-9.-]{1,30}$/.test(u)?u:''; })();
const PAYLINK=(function(){ const l=String(((cfg.payments||{}).link)||'').trim(); return /^https:\/\//i.test(l)?l:''; })();
const QR=(function(){ const l=String(((cfg.payments||{}).qr_url)||'').trim(); return /^https:\/\//i.test(l)?l:''; })();

// what the member sent
let intentId=null, text='', kind='text', mediaCaption='', mediaName='';
const mtype=String(msg.type||'text');
if(mtype==='text') text=((msg.text&&msg.text.body)||'').trim();
else if(mtype==='interactive'){ const ir=msg.interactive||{}; if(ir.type==='list_reply'&&ir.list_reply) intentId=ir.list_reply.id; else if(ir.type==='button_reply'&&ir.button_reply) intentId=ir.button_reply.id; else if(ir.type==='nfm_reply') kind='media'; }
else if(mtype==='button'){ text=String((msg.button&&(msg.button.text||msg.button.payload))||'').trim(); }   // quick-reply button of a template
else if(mtype==='reaction'){ kind='reaction'; }
else if(mtype==='request_welcome'){ /* the member opened the chat for the first time: greet them (text stays empty) */ }
else if(mtype==='system'){ kind='system'; }   /* e.g. "User A changed from ... to ...": kept for staff, no reply */
else { kind='media'; const m=msg[mtype]||{}; mediaCaption=String(m.caption||'').trim(); mediaName=String(m.filename||'').trim(); }
/* the kinds that are a file (kept in the private store) and the kinds that are words */
const FILE_TYPES=['image','video','audio','document','sticker'];
const MSG_LABEL={contacts:'contact',interactive:'form',unsupported:'unsupported message',unknown:'unsupported message'};
const oneLine=(v,n)=>String(v==null?'':v).replace(/\s+/g,' ').trim().slice(0,n||200);
/* what the member sent, in words: a contact card, a location, an order, form answers, or a kind WhatsApp does not pass on */
function describeOther(){
  if(mtype==='contacts'){ const list=Array.isArray(msg.contacts)?msg.contacts:[];
    return list.slice(0,10).map(c=>{ c=c||{}; const nm=oneLine((c.name&&(c.name.formatted_name||[c.name.first_name,c.name.last_name].filter(Boolean).join(' ')))||'Contact',80);
      const ph=(Array.isArray(c.phones)?c.phones:[]).map(p=>oneLine(p&&(p.phone||p.wa_id),30)+((p&&p.type)?(' ('+oneLine(p.type,12).toLowerCase()+')'):'')).filter(x=>x.trim());
      const em=(Array.isArray(c.emails)?c.emails:[]).map(e=>oneLine(e&&e.email,80)).filter(Boolean); const org=oneLine(c.org&&c.org.company,80);
      return nm+(org?(', '+org):'')+(ph.length?('\nPhone: '+ph.join(', ')):'')+(em.length?('\nEmail: '+em.join(', ')):''); }).join('\n\n')+(list.length>10?('\n\nand '+(list.length-10)+' more'):''); }
  if(mtype==='location'){ const l=msg.location||{}; const la=Number(l.latitude), lo=Number(l.longitude); const ok=l.latitude!=null&&l.longitude!=null&&isFinite(la)&&isFinite(lo)&&Math.abs(la)<=90&&Math.abs(lo)<=180;
    return [oneLine(l.name,100),oneLine(l.address,200),ok?('https://maps.google.com/?q='+la+','+lo):''].filter(Boolean).join('\n'); }
  if(mtype==='order'){ const o=msg.order||{}; const items=Array.isArray(o.product_items)?o.product_items:[];
    return items.length+' item(s)'+(items.length?(': '+items.slice(0,20).map(i=>oneLine(i&&i.product_retailer_id,40)+' x'+(Number(i&&i.quantity)||1)+((i&&i.item_price!=null)?(' @ '+oneLine(i.item_price,12)+' '+oneLine(i.currency,5)):'')).join('; ')):'')+(o.text?('\nNote: '+oneLine(o.text,300)):''); }
  if(mtype==='interactive'){ const ir=msg.interactive||{}; if(ir.type==='nfm_reply'&&ir.nfm_reply){ let j=ir.nfm_reply.response_json; try{ j=JSON.stringify(typeof j==='string'?JSON.parse(j):j); }catch(e){ j=String(j||''); } return 'Form answers: '+oneLine(j,1500); } return ''; }
  if(mtype==='unsupported'||mtype==='unknown'){ const e=(Array.isArray(msg.errors)&&msg.errors[0])||{};
    return 'WhatsApp does not pass this kind of message to businesses (for example a poll, an event, a view-once photo or a deleted message). Ask the member to send it as text, a photo or a document.'+(e.title?(' WhatsApp says: '+oneLine(e.title,120)+'.'):''); }
  return '';
}
const otherDetail=(kind==='media'&&!FILE_TYPES.includes(mtype))?describeOther():'';
/* notes for staff: the member forwarded this, or wrote after tapping an ad */
const _ctx=msg.context||{}; const _ref=msg.referral||null;
const staffNote=((_ctx.forwarded||_ctx.frequently_forwarded)?'[forwarded] ':'');
const adNote=_ref?('\n[came from an ad'+(oneLine(_ref.headline,80)?(': '+oneLine(_ref.headline,80)):'')+(/^https?:/i.test(String(_ref.source_url||''))?(' '+oneLine(_ref.source_url,200)):'')+']'):'';
const inBody0=kind==='reaction'?('[reaction '+String((msg.reaction&&msg.reaction.emoji)||'')+']')
  : kind==='system'?('[system] '+String((msg.system&&(msg.system.body||msg.system.type))||'')).trim()
  : kind==='media'?('['+(MSG_LABEL[mtype]||mtype)+']'+(mediaName?(' '+mediaName):'')+(mediaCaption?(' '+mediaCaption):'')+(otherDetail?('\n'+otherDetail):''))
  : (text||(intentId?('[tapped] '+intentId):('['+mtype+']')));

// member + recent conversation (read before this message is stored)
const _digits=from.replace(/[^0-9]/g,''); const _last10=_digits.slice(-10);
let member=null;
/* the same number key as public.wa_phone_key (the Inbox): digits only, 10 digits or 0 + 10 digits = India.
   Members saved as typed ("+91 98765 00003", "098765 00003") are found too; a different country's
   number that only shares the last 10 digits is not. */
const phoneKey=(p)=>{ const d=String(p||'').replace(/[^0-9]/g,''); return d.length===10?('91'+d):((d.length===11&&d[0]==='0')?('91'+d.slice(1)):d); };
const _key=phoneKey(from);
try{ const mr=await get('members?tenant_id=eq.'+tid+'&or=(phone.eq.'+encodeURIComponent(_digits)+',phone.like.*'+_last10+',phone.like.*'+_digits.slice(-4)+')&select=id,full_name,membership_tier,status,phone&order=created_at&limit=50');
  member=Array.isArray(mr)?(mr.find(m=>phoneKey(m.phone)===_key)||null):null; }catch(e){}
const first=member?(String(member.full_name||'').trim().split(/\s+/)[0]||''):'';
let history=[];
try{ const hr=await get('wa_messages?tenant_id=eq.'+tid+'&phone=eq.'+encodeURIComponent(from)+'&direction=in.(in,out)&order=created_at.desc&limit=8&select=direction,body,created_at'); history=Array.isArray(hr)?hr.slice().reverse():[]; }catch(e){}
const _lastTs=history.length?new Date(history[history.length-1].created_at).getTime():0;
const isNewSession=!history.length||((Date.now()-_lastTs)>6*3600*1000);

// store the member's message first: a repeat of the same WhatsApp id means Meta retried, so stop
async function storeRow(row){
  const full=Object.assign({tenant_id:tid,phone:from,member_id:member?member.id:null},row);
  let r=await H.httpRequest({method:'POST',url:SUPA+'/rest/v1/wa_messages',headers:{...sH,Prefer:'return=minimal'},body:JSON.stringify(full),returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:8000});
  if(r.statusCode===409) return 'duplicate';
  if(r.statusCode>=400){
    // before sql/wa_inbox.sql: the new columns don't exist yet, store the old way
    const legacy={tenant_id:full.tenant_id,phone:full.phone,member_id:full.member_id,direction:full.direction,body:full.body,msg_type:full.msg_type,intent:full.intent};
    r=await H.httpRequest({method:'POST',url:SUPA+'/rest/v1/wa_messages',headers:{...sH,Prefer:'return=minimal'},body:JSON.stringify(legacy),returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:8000});
    return r.statusCode<300?'legacy':'error';
  }
  return 'stored';
}
/* the whole message (WhatsApp allows 4,096 characters); anything longer is visibly marked as cut */
const inBody=(kind==='reaction'||kind==='system')?inBody0:(staffNote+inBody0+adNote);
const _inStr=String(inBody);
const stored=await storeRow({direction:'in',body:_inStr.length>4096?(cut(_inStr,4090)+' [cut]'):_inStr,msg_type:mtype,intent:intentId,wamid:msg.id||null,sender_kind:'member'});
if(stored==='duplicate') return {ok:true,from,duplicate:true};

/* a photo or file the member sent: Meta keeps it for a short time only, so it is copied now to the club's private
   store (bucket wa-media, folder = club id) and the stored message points at it; the Inbox shows it to staff.
   Anything that fails here leaves the message as "[image]" / "[document] name"; the member still gets a reply. */
const MEDIA_MAX=10*1024*1024;
/* the bytes go to the store through the File Upload Relay workflow (an HTTP Request node), because a Code node on this n8n cannot send a binary body */
const RELAY='https://n8n.example.com/webhook/file-upload-relay', CONFIRM='__CONFIRM_TOKEN__';
async function keepMedia(){
  const m=msg[mtype]||{}; const mid=String(m.id||'').trim(); if(!mid) return {why:'skipped: no media id'}; if(!tenant.wa_token) return {why:'skipped: no WhatsApp token'}; if(!/^[A-Za-z0-9_-]{1,80}$/.test(mid)) return {why:'skipped: odd media id'};
  let step='info';
  try{
    const info=await H.httpRequest({method:'GET',url:G+encodeURIComponent(mid)+'?fields=url,mime_type,file_size',headers:{Authorization:'Bearer '+tenant.wa_token},json:true,returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:15000});
    let ib=info.body; if(typeof ib==='string'){ try{ ib=JSON.parse(ib); }catch(e){ ib=null; } }
    if(info.statusCode>=300||!ib||!ib.url) return {why:'failed: Meta media lookup HTTP '+info.statusCode+' '+String(ib&&ib.error?(ib.error.message||''):'').slice(0,120)};
    if(Number(ib.file_size)>MEDIA_MAX) return {why:'skipped: too large ('+Math.round(Number(ib.file_size)/1048576)+' MB)'};
    step='download';
    const mime=String(ib.mime_type||m.mime_type||'application/octet-stream').split(';')[0].trim().toLowerCase();
    const dl=await H.httpRequest({method:'GET',url:ib.url,headers:{Authorization:'Bearer '+tenant.wa_token},encoding:'arraybuffer',returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:60000});
    let bytes=dl.body;
