    else{ const rows=list.slice(0,10).map(e=>({id:'act:reg:'+e.id,title:cut(e.title||'Event',24),description:((e.fee?('Rs '+e.fee):'Free'))+' | '+(e.kind||'event')}));
      reply={messaging_product:'whatsapp',to:from,type:'interactive',interactive:{type:'list',header:{type:'text',text:'Events & Tournaments'},body:{text:cfg.events_intro||'Tap an event to register.'},footer:(FOOT?{text:FOOT}:undefined),action:{button:'View events',sections:[{title:'Upcoming',rows}]}}}; }
  }
  else if(intentId.indexOf('act:reg:')===0){ const eid=encodeURIComponent(intentId.slice(8));
    const ev=await get('events?id=eq.'+eid+'&tenant_id=eq.'+tid+'&select=id,title,fee,is_open,starts_at');
