    if(!event||!event.is_open||(event.starts_at&&new Date(event.starts_at)<dayStart())){ reply=textMsg('Sorry, that event is not open for registration.'); }
    else{ /* an active registration of this member (any phone format, or the member's own record) blocks a second one;
             a registration staff cancelled does not */
      const orP=['phone.eq.'+encodeURIComponent(from),'phone.like.*'+_last10].concat(member?['member_id.eq.'+member.id]:[]);
      const ex=await get('event_registrations?event_id=eq.'+eid+'&or=('+orP.join(',')+')&status=neq.cancelled&select=id,status,phone,member_id&order=created_at&limit=20');
      const exRow=Array.isArray(ex)?(ex.find(r=>(member&&r.member_id===member.id)||phoneKey(r.phone)===_key)||null):null;
      if(exRow){ reply=textMsg('You are already registered for '+event.title+' ('+exRow.status+').'); }
      else{ const ir=await H.httpRequest({method:'POST',url:SUPA+'/rest/v1/event_registrations',headers:{...sH,Prefer:'return=representation'},body:JSON.stringify({tenant_id:tid,event_id:event.id,member_id:member?member.id:null,name:(member&&member.full_name)||('WhatsApp '+from.slice(-4)),phone:from,source:'WhatsApp',status:'registered'}),json:true,returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:12000});
        if(ir.statusCode===409){ reply=textMsg('You are already registered for '+event.title+'.'); }
        else if(ir.statusCode>=300){ reply=buttons('Sorry, we could not register you for '+event.title+' just now. Please try again in a minute, or talk to our team.',[{id:'menu:human',title:'Talk to Team'}]); }
        else{ const ins=ir.body; const st=((Array.isArray(ins)?ins[0]:ins)||{}).status;
        /* the database puts a registration on the waitlist when the event is full (enforce_event_capacity) */
        reply=textMsg(st==='waitlist'?('This event is full - you are WAITLISTED for '+event.title+'.'):('You are registered for '+event.title+'! '+(event.fee?('Fee: Rs '+event.fee+'.'):'Free entry.'))); } } }
  }
  else{ const rt=await aiReply(text||'menu'); reply=rt?textMsg(rt):mainMenu('How can I help?'); }
}
else{
