// ---- send, and store what was sent (with its WhatsApp id and status) ----
async function sendAndStore(payload,intent){
  let wamid=null, ok=false, err=null, code=null;
  if(tenant.wa_token&&tenant.wa_phone_number_id){
    try{ const r=await H.httpRequest({method:'POST',url:G+tenant.wa_phone_number_id+'/messages',headers:{Authorization:'Bearer '+tenant.wa_token,'Content-Type':'application/json'},body:JSON.stringify(payload),returnFullResponse:true,ignoreHttpStatusErrors:true});
      let rb=r.body; if(typeof rb==='string'){ try{ rb=JSON.parse(rb); }catch(e){} }
      ok=r.statusCode<400; wamid=(rb&&rb.messages&&rb.messages[0]&&rb.messages[0].id)||null;
      if(!ok){ const eo=(rb&&rb.error)||{}; code=eo.code!=null?Number(eo.code):null; err=String(eo.error_user_msg||(eo.error_data&&eo.error_data.details)||eo.message||(typeof r.body==='string'?r.body:JSON.stringify(r.body))).slice(0,300); } }
    catch(e){ err=String(e.message||e).slice(0,300); }
  } else err='WhatsApp is not set up for this club';
  await storeRow({direction:'out',body:cut(replyText(payload),4096),msg_type:payload.type,intent:intent||null,wamid,sender_kind:'bot',
    status:ok?'sent':'failed',error_code:ok?null:code,error_title:ok?null:err,media_url:payload.type==='image'?((payload.image&&payload.image.link)||null):null});
  return {ok,wamid,err};
}
let preRes=null; if(pre) preRes=await sendAndStore(pre,null);
