    try{ const lr=await H.httpRequest({method:'POST',url:LEAD,headers:{'Content-Type':'application/json'},body:JSON.stringify({tenant:tenant.slug,name:(member&&member.full_name)||('WhatsApp '+from.slice(-4)),phone:from,message:'WhatsApp bot ['+capture.intent+']'+(text?(': '+text):''),source:'WhatsApp bot'}),returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:12000}); leadPosted=!!lr&&lr.statusCode>=200&&lr.statusCode<300; }catch(e){}
    if(leadPosted){ try{ await rpc('wa_bot_lead_posted',{p_tenant:tid,p_phone:from,p_intent:capture.intent}); }catch(e){} }
  }
}
return {ok:true,tenant:tenant.name,from,member:member?member.id:null,new_session:isNewSession,history:history.length,stored,media:mediaNote,
  kind,intent:intentId||(kind==='text'?('text:'+low.slice(0,24)):kind),reply_type:reply&&reply.type,captured:capture&&capture.intent||null,
  lead_posted:leadPosted,sent:res.ok,send_error:res.err||null,banner_sent:preRes?preRes.ok:null};
}

const results=[];
for(const value of changes){
  const pnid=value.metadata&&value.metadata.phone_number_id;
  const club=await tenantFor(pnid); const check=clubCheck(club);
  if(check==='mismatch'){ results.push({ok:false,error:'signature does not match this club\'s app secret: its part of the event was ignored'}); continue; }
  // ---- delivery statuses ----
  if(Array.isArray(value.statuses)&&value.statuses.length){
    const t=club; const tid=t?t.id:null;
    let applied=0;
    for(const st of value.statuses){
      if(!st||!st.id||!st.status) continue;
      if(!tid) continue;   /* a phone number id of no club here: never touch any club's messages or campaigns */
      const stType=String(st.status).toLowerCase();
      const ts=st.timestamp?new Date(parseInt(st.timestamp,10)*1000).toISOString():new Date().toISOString();
      const e=(st.errors&&st.errors[0])||null;
      let broadcastId=null, tracked=false;
      if(tid){
        /* is this message tracked (a status row exists)? untracked ones are campaigns from before tracking */
        const s=await get('wa_message_status?wamid=eq.'+encodeURIComponent(st.id)+'&select=broadcast_id,tenant_id');
        tracked=Array.isArray(s)&&s.length>0;
        if(tracked&&s[0].tenant_id&&s[0].tenant_id!==tid) continue;   /* another club's message: not this club's to change */
        broadcastId=tracked?s[0].broadcast_id:null;
        /* with a verified signature, a status that arrives before its message is stored is kept; the message picks it up */
        const a=await rpc('wa_status_apply',{p_wamid:String(st.id),p_tenant:tid,p_status:stType,p_at:ts,
          p_phone:st.recipient_id?String(st.recipient_id).replace(/[^0-9]/g,''):null,
          p_code:e&&e.code!=null?Number(e.code):null,p_title:e?(e.title||null):null,
          p_detail:e?((e.error_data&&e.error_data.details)||e.message||null):null,
          p_conv:(st.conversation&&st.conversation.id)||null,p_category:(st.pricing&&st.pricing.category)||null,
          p_billable:(st.pricing&&typeof st.pricing.billable==='boolean')?st.pricing.billable:null,p_create:check==='verified'});
        if(a.ok) applied++;
      }
      // the campaign's recipient list (what reports read), as before
      if(!(stType==='read'||stType==='delivered'||stType==='failed')) continue;
      let bRows=null;
      if(broadcastId) bRows=await get('broadcasts?id=eq.'+broadcastId+'&tenant_id=eq.'+tid+'&select=id,body');
      else if(tracked) continue; /* a bot, staff or test message: there is no campaign list to update */
      else bRows=await get('broadcasts?'+(tid?('tenant_id=eq.'+tid+'&'):'')+'status=in.(sent,sending)&order=sent_at.desc&limit=15&select=id,body');
      for(const bRow of (Array.isArray(bRows)?bRows:[])){
        if(!bRow.body||bRow.body.indexOf(st.id)===-1) continue;
        let cfgB={}; try{ cfgB=JSON.parse(bRow.body); }catch(err){}
        if(!Array.isArray(cfgB.recipients)) continue;
        let updated=false;
        for(const recip of cfgB.recipients){
          if(recip.wamid!==st.id) continue;
          if(stType==='read'){ recip.status='read'; recip.read_at=ts; if(!recip.delivered_at) recip.delivered_at=ts; updated=true; }
          else if(stType==='delivered'){ if(recip.status!=='read'){ recip.status='delivered'; recip.delivered_at=ts; updated=true; } }
          else if(stType==='failed'){ if(recip.status!=='read'&&recip.status!=='delivered'){ recip.status='failed'; recip.failed_at=ts; recip.error=(e&&e.title)||'Failed'; updated=true; } }
          break;
        }
        if(updated){
          if(!cfgB.stats) cfgB.stats={sent:cfgB.recipients.length,delivered:0,read:0,failed:0};
          cfgB.stats.read=cfgB.recipients.filter(x=>x.status==='read').length;
          cfgB.stats.delivered=cfgB.recipients.filter(x=>x.status==='delivered'||x.status==='read').length;
          cfgB.stats.failed=cfgB.recipients.filter(x=>x.status==='failed').length;
          cfgB.stats.updated_at=new Date().toISOString();
          await H.httpRequest({method:'PATCH',url:SUPA+'/rest/v1/broadcasts?id=eq.'+bRow.id,headers:{...sH,Prefer:'return=minimal'},body:JSON.stringify({body:JSON.stringify(cfgB)}),returnFullResponse:true,ignoreHttpStatusErrors:true});
        }
        break;
      }
    }
    results.push({type:'statuses',count:value.statuses.length,applied});
  }
  // ---- member messages ----
  for(const msg of (value.messages||[])){
    if(!msg||!msg.from||!pnid) continue;
    const tenant=await tenantFor(pnid);
    if(!tenant){ results.push({ok:false,error:'no tenant for '+pnid}); continue; }
    results.push(await handleMessage(tenant,msg));
  }
}
return [{json:{ok:true,signature:verified,results}}];


